import React, { useState, useMemo } from "react";
import FileDropzone from "./FileDropzone";
import AlgorithmSelector from "./AlgorithmSelector";
import GlobalCounter from "./GlobalCounter";
import ImagesGrid from "./ImagesGrid";
import ImageDetail from "./ImageDetail";
import Cost from "./Cost";
import defaultPalettes from "data/palettes";
import closerColor, { algorithms } from "utils/closerColor";
import imageColors from "selectors/imageColors";

const DEFAULT_COST = 0.04;
const selectedPalette = "pixel-bela";
const palette = defaultPalettes[selectedPalette];

const App = () => {
  const [cost, setCost] = useState(localStorage.getItem("cost") || DEFAULT_COST);
  const [images, setImages] = useState({});
  const [selectedImage, setSelectedImage] = useState(null);
  const [selectedAlgorithm, setSelectedAlgorithm] = useState(algorithms.DELTA_E00);

  const moveSelectedImage = (move) => {
    const imagesKeys = Object.keys(images);
    const index = imagesKeys.indexOf(selectedImage);
    const newIndex =
      index + move < 0
        ? imagesKeys.length - 1
        : index + move > imagesKeys.length - 1
        ? 0
        : index + move;

    setSelectedImage(imagesKeys[newIndex]);
  };

  const deleteImage = (id) => {
    setImages((prevImages) => {
      const nextImages = { ...prevImages };
      delete nextImages[id];
      return nextImages;
    });

    if (selectedImage === id) {
      setSelectedImage(null);
    }
  };

  const { colorsImage, colorsGlobal, globalCount } = useMemo(() => {
    const colorsImage = {};
    const colorsGlobal = {};
    let globalCount = 0;

    if (palette) {
      closerColor.from(palette, selectedAlgorithm);

      Object.keys(images).forEach((key) => {
        const img = images[key];

        const { colorImage, colorGlobal, count } = imageColors({
          img,
          closerColor,
          palette,
          selectedAlgorithm,
        });

        colorsImage[key] = colorImage;
        globalCount += count;
        Object.keys(colorGlobal).forEach((p) => {
          if (!colorsGlobal[p]) {
            colorsGlobal[p] = colorGlobal[p];
          } else {
            colorsGlobal[p].count += colorGlobal[p].count;
          }
        });
      });
    }

    return { colorsImage, colorsGlobal, globalCount };
  }, [images, palette, selectedAlgorithm]);

  const sprites = Object.keys(images).length;

  return (
    <main className="h-screen flex flex-col font-sans text-white p-6 gap-4 w-full mx-auto xl:w-3/4">
      <div className="flex items-stretch mx-auto text-gray-500 uppercase text-base gap-4 ">
        <FileDropzone {...{ setImages }} />
        <Cost {...{ cost, setCost }} />
      </div>
      <AlgorithmSelector {...{ selectedAlgorithm, setSelectedAlgorithm }} />
      {selectedPalette && sprites > 0 && (
        <GlobalCounter
          pixels={globalCount}
          sprites={sprites}
          cost={(globalCount * cost).toFixed(2)}
          colorsGlobal={colorsGlobal}
        />
      )}
      {Object.keys(images).length > 0 && (
        <ImagesGrid
          {...{
            palette,
            images,
            selectedPalette,
            colorsImage,
            cost,
            setSelectedImage,
            deleteImage,
          }}
        />
      )}
      {selectedImage && (
        <ImageDetail
          id={selectedImage}
          image={images[selectedImage]}
          colors={colorsImage[selectedImage]}
          {...{
            palette,
            selectedPalette,
            setSelectedImage,
            cost,
            moveSelectedImage,
          }}
        />
      )}
    </main>
  );
};

export default App;
